# Validation
ALLOWED_POS = {"noun", "verb", "adj", "adv", "num", "intj", "prep", "pron", "conj", "det", "phrase"}
for item in part3_data:
    assert len(item["vi"]) <= 35, f"vi too long: {item['hw']} -> {len(item['vi'])} chars: {item['vi']}"
    assert item["pos"] in ALLOWED_POS, f"bad pos: {item['hw']} -> {item['pos']}"
    if item["pos"] != "phrase" or item["ipa"]:
        assert item["ipa"].startswith("/") and item["ipa"].endswith("/"), f"bad ipa slashes: {item['hw']} -> {item['ipa']}"
        assert item["ipa"].count("/") == 2, f"ipa slash count != 2: {item['hw']} -> {item['ipa']}"
    assert item["status"] == "reviewed"

with open("scratch/b31_r01_p3.json", "w", encoding="utf-8") as f:
    json.dump(part3_data, f, ensure_ascii=False, indent=2)

print(f"Validated and saved {len(part3_data)} items for Part 3")
